import React, { useState } from 'react';
import { StyleSheet, Text, View, TextInput, TouchableOpacity, ActivityIndicator, KeyboardAvoidingView, Platform } from 'react-native';
import { api } from '../api';

interface LoginScreenProps {
  onOtpRequested: (mobile: string, testOtp?: string) => void;
}

export const LoginScreen: React.FC<LoginScreenProps> = ({ onOtpRequested }) => {
  const [mobileNumber, setMobileNumber] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleRequestOtp = async () => {
    if (!mobileNumber) {
      setError('Please enter your mobile number.');
      return;
    }
    setLoading(true);
    setError('');
    try {
      const res = await api.post('/auth/otp/request', { mobileNumber });
      onOtpRequested(mobileNumber, res.otpCode);
    } catch (err: any) {
      setError(err.message || 'Failed to send OTP. Please check your network.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      style={styles.container}
    >
      <View style={styles.card}>
        <Text style={styles.emoji}>🏥</Text>
        <Text style={styles.title}>Amar Hospital</Text>
        <Text style={styles.subtitle}>PATIENT MOBILE APP</Text>

        <Text style={styles.tagline}>
          Simple and secure token registration. Enter your mobile number below to request access.
        </Text>

        {error ? <Text style={styles.errorText}>{error}</Text> : null}

        <View style={styles.formGroup}>
          <Text style={styles.label}>Mobile Number</Text>
          <TextInput
            style={styles.input}
            placeholder="+91 98765 43210"
            placeholderTextColor="#8892b0"
            keyboardType="phone-pad"
            value={mobileNumber}
            onChangeText={(text) => { setMobileNumber(text); setError(''); }}
          />
        </View>

        <TouchableOpacity
          style={styles.button}
          onPress={handleRequestOtp}
          disabled={loading}
        >
          {loading ? (
            <ActivityIndicator color="#0d1117" />
          ) : (
            <Text style={styles.buttonText}>Get Verification OTP</Text>
          )}
        </TouchableOpacity>

        <View style={styles.noteBox}>
          <Text style={styles.noteTitle}>Passwordless Login Info:</Text>
          <Text style={styles.noteContent}>
            No passwords are required. Log in anytime using your phone and a temporary OTP. Session remains active for 90 days.
          </Text>
        </View>
      </View>
    </KeyboardAvoidingView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#0d1117',
    alignItems: 'center',
    justifyContent: 'center',
    padding: 24,
  },
  card: {
    backgroundColor: '#161b22',
    borderWidth: 1,
    borderColor: '#21262d',
    borderRadius: 16,
    padding: 32,
    width: '100%',
    maxWidth: 400,
    alignItems: 'center',
  },
  emoji: {
    fontSize: 48,
    marginBottom: 16,
  },
  title: {
    fontSize: 28,
    fontWeight: '800',
    color: '#ffffff',
    textAlign: 'center',
  },
  subtitle: {
    fontSize: 11,
    fontWeight: '700',
    color: '#0ea5e9',
    letterSpacing: 2,
    marginTop: 4,
    marginBottom: 20,
    textAlign: 'center',
  },
  tagline: {
    fontSize: 14,
    color: '#8892b0',
    textAlign: 'center',
    lineHeight: 20,
    marginBottom: 24,
  },
  formGroup: {
    width: '100%',
    marginBottom: 20,
  },
  label: {
    color: '#8892b0',
    fontSize: 13,
    fontWeight: '600',
    marginBottom: 8,
  },
  input: {
    backgroundColor: '#0d1117',
    borderWidth: 1,
    borderColor: '#21262d',
    borderRadius: 8,
    paddingHorizontal: 16,
    paddingVertical: 12,
    color: '#ffffff',
    fontSize: 16,
  },
  button: {
    backgroundColor: '#0ea5e9',
    borderRadius: 8,
    paddingVertical: 14,
    width: '100%',
    alignItems: 'center',
    justifyContent: 'center',
    marginTop: 10,
    shadowColor: '#0ea5e9',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.2,
    shadowRadius: 8,
    elevation: 4,
  },
  buttonText: {
    color: '#0d1117',
    fontSize: 16,
    fontWeight: '700',
  },
  errorText: {
    color: '#f43f5e',
    fontSize: 14,
    fontWeight: '500',
    marginBottom: 16,
    textAlign: 'center',
  },
  noteBox: {
    marginTop: 28,
    borderTopWidth: 1,
    borderTopColor: '#21262d',
    paddingTop: 16,
    width: '100%',
  },
  noteTitle: {
    color: '#0ea5e9',
    fontSize: 12,
    fontWeight: '700',
    marginBottom: 4,
  },
  noteContent: {
    color: '#8892b0',
    fontSize: 12,
    lineHeight: 16,
  },
});
